            parts.append(('product ' + str(x['n']) + ': ' if n > 1 else '') + act + '.')
        cal.append('- ' + sp(d) + ' (' + d.isoformat() + ')' + (' [today]' if d == today else '') + ': ' + ' '.join(parts))
