                             + str(SPEC.get('first_ask_all') or SPEC.get('first_ask') or ''))
    vars['debt_state'] = 'ok' if ok else 'error'
except Exception as e:
    vars['debt_state'] = 'error'
    vars['debt_error'] = str(e)

